import{I as s,o as d,c as g,j as t,a as i,J as a,w as r,b6 as h}from"./chunks/framework.COUcLbTA.js";const c={style:{margin:"50px 0"}},m=JSON.parse('{"title":"좋은 아이디어 찾기 - 사용자 요구에서 누군가 비용을 지불하는 지점까지","description":"일상의 문제점에서 비즈니스 기회를 발견하는 법을 배우고, 요구사항 분석의 체계적인 방법론을 익혀 평범한 생각을 사용자가 기꺼이 비용을 지불할 제품 개념으로 다듬습니다.","frontmatter":{"title":"좋은 아이디어 찾기 - 사용자 요구에서 누군가 비용을 지불하는 지점까지","description":"일상의 문제점에서 비즈니스 기회를 발견하는 법을 배우고, 요구사항 분석의 체계적인 방법론을 익혀 평범한 생각을 사용자가 기꺼이 비용을 지불할 제품 개념으로 다듬습니다."},"headers":[],"relativePath":"ko-kr/stage-1/finding-great-idea/index.md","filePath":"ko-kr/stage-1/finding-great-idea/index.md"}'),u={name:"ko-kr/stage-1/finding-great-idea/index.md"},A=Object.assign(u,{setup(b){const p="약 <strong>3시간</strong>";return(k,l)=>{const n=s("ChapterIntroduction"),o=s("StepBar"),e=s("ClientOnly");return d(),g("div",null,[l[1]||(l[1]=t("h1",{id:"초급-2-좋은-아이디어-찾기",tabindex:"-1"},[i("초급 2: 좋은 아이디어 찾기 "),t("a",{class:"header-anchor",href:"#초급-2-좋은-아이디어-찾기","aria-label":"Permalink to “초급 2: 좋은 아이디어 찾기”"},"​")],-1)),l[2]||(l[2]=t("h2",{id:"이-장의-가이드",tabindex:"-1"},[i("이 장의 가이드 "),t("a",{class:"header-anchor",href:"#이-장의-가이드","aria-label":"Permalink to “이 장의 가이드”"},"​")],-1)),a(n,{duration:p,tags:["요구 발굴","제품 사고","사용자 분석","비즈니스 모델"],coreOutput:"검증된 제품 개념 3개",expectedOutput:"실행 가능한 창업/제품 방향"},{default:r(()=>[...l[0]||(l[0]=[t("p",null,[i("앞에서 우리는 AI IDE로 무언가를 만드는 법을 배웠습니다. 하지만 더 근본적인 문제가 하나 있습니다. "),t("strong",null,"무엇을 만들 것인가?")],-1),t("p",null,[i("많은 사람은 시작하자마자 “AI 도구 하나 만들자”, “소셜 플랫폼 하나 하자”라고 생각하지만, 결과물은 아무도 쓰지 않습니다. 문제는 어디에 있을까요? "),t("strong",null,"진짜 요구를 찾지 못했기 때문입니다"),i(".")],-1),t("p",null,[i("더 냉혹한 현실도 있습니다. "),t("strong",null,"많은 제품은 문제를 해결했는데도 사용자가 비용을 지불하려 하지 않습니다.")],-1),t("p",null,"이번 장에서는 샤오밍의 이야기를 통해, 만들 가치가 있는 제품 방향을 찾는 법을 배웁니다.",-1),t("p",null,[i("이 장을 마치면 당신은 "),t("strong",null,"좋은 아이디어를 찾는 완전한 방법론"),i("과 검증된 제품 개념 3개를 갖게 됩니다.")],-1)])]),_:1}),t("div",c,[a(e,null,{default:r(()=>[a(o,{active:0,items:[{title:"Step 1",description:"판단 기준 세우기"},{title:"Step 2",description:"일상 문제점 발굴"},{title:"Step 3",description:"사람군을 가로로 나누기"},{title:"Step 4",description:"장면을 세로로 깊게 파기"},{title:"Step 5",description:"요구의 진위 검증"},{title:"Step 6",description:"제품 개념 다듬기"}]})]),_:1})]),l[3]||(l[3]=h(`<h2 id="step-1-판단-기준-세우기-어떤-요구에-사용자가-비용을-지불할까" tabindex="-1">Step 1: 판단 기준 세우기 - 어떤 요구에 사용자가 비용을 지불할까 <a class="header-anchor" href="#step-1-판단-기준-세우기-어떤-요구에-사용자가-비용을-지불할까" aria-label="Permalink to “Step 1: 판단 기준 세우기 - 어떤 요구에 사용자가 비용을 지불할까”">​</a></h2><div class="warning custom-block"><p class="custom-block-title">이 장은 왜 중요한가?</p><p>누군가는 이상하게 느낄 수 있습니다. “이건 Vibe Coding을 가르치는 수업 아닌가? 왜 먼저 ‘요구 찾기’를 배워야 하지? 바로 코드 쓰면 안 되나?”</p><p>맞습니다. 시중의 많은 프로그래밍 수업은 바로 프로젝트를 만들게 합니다. Todo List 만들기, 계산기 만들기, 개인 블로그 만들기... 이런 프로젝트는 문법과 도구에 익숙해지는 데 분명 도움 됩니다. 하지만 문제는 다음입니다.</p><p><strong>방향이 틀리면, 깊이 들어갈수록 더 많이 틀립니다.</strong></p><p>상상해 보세요.</p><ul><li>2주 동안 “일정 관리 시스템”을 만들었지만 시장에는 이미 더 좋은 것이 100개 있습니다.</li><li>“사진으로 칼로리 계산”을 만들었지만 사용자는 한 번 쓰고 삭제합니다.</li><li>“개인 가계부”를 만들었지만 당신 자신도 쓰기 귀찮아합니다.</li></ul><p>이런 프로젝트를 완성한 뒤 이력서에 쓸 수 있을까요? 아마 어렵습니다. <strong>진짜 문제를 해결하지 않았고, 진짜 가치를 만들지 않았기 때문입니다</strong>.</p><p>더 냉정하게 말하면, 어차피 시간을 들여 배울 거라면 왜 더 좋은 결과를 추구하지 않을까요?</p><p>Vibe Coding이 우리에게 아이디어를 빠르게 제품으로 바꿀 수 있게 해 준다면, 우리는 더욱 <strong>만들 가치가 있는 아이디어를 찾는 법</strong>을 배워야 합니다. 실전에 가장 가까운 방식으로 훈련해야 합니다. “연습 프로젝트”를 만드는 것이 아니라 “누군가 기꺼이 사용할 제품”을 만드는 것입니다.</p><p>그래서 우리는 먼저 “좋은 아이디어 찾기”를 배웁니다.</p><hr><p><strong>필자는 개인적으로</strong> 시간이 매우 소중하다고 생각합니다. <strong>할 거면 가장 잘해야 합니다.</strong> 그렇지 않다면 왜 놀러 가지 않을까요? 책임감으로서 필자도 최선을 다해 당신이 가장 잘할 수 있도록 지원하겠습니다.</p><p>모든 사람이 당신이 잘할 수 있다고 믿지 않더라도, 필자는 흔들림 없이 당신이 가장 잘할 수 있기를 바랍니다. vibecoding으로 제품을 만들기로 했다면, 자신이 어디까지 갈 수 있는지 한번 시험해 봅시다!</p></div><hr><h2 id="시작-독립-개발자-샤오밍의-이야기" tabindex="-1">시작: 독립 개발자 샤오밍의 이야기 <a class="header-anchor" href="#시작-독립-개발자-샤오밍의-이야기" aria-label="Permalink to “시작: 독립 개발자 샤오밍의 이야기”">​</a></h2><p>샤오밍은 프로그래머이고, 일한 지 3년이 되었습니다. 어느 날 문득 이런 생각이 떠올랐습니다. 피트니스 APP을 하나 만들어 보면 어떨까? 사용자가 운동 계획을 세우고 훈련 데이터를 기록하도록 돕는 앱입니다. 이 생각에 그는 매우 흥분했고, 드디어 만들 수 있는 프로젝트를 찾았다고 느꼈습니다.</p><p>그다음 1년 동안 샤오밍은 거의 모든 여가 시간을 쏟아부었습니다. 그는 기능이 매우 완전한 APP을 만들었습니다. 수업 모듈, 출석 체크 시스템, 커뮤니티 기능, 데이터 분석까지 있어야 할 것은 다 있었습니다. 인터페이스도 꽤 보기 좋았습니다. 적어도 본인은 꽤 만족했습니다.</p><p>출시 당일, 샤오밍은 큰 기대를 품었습니다. 홍보에도 적지 않은 돈을 썼고, 첫 달에 5만 명이 다운로드했습니다. 시작은 좋아 보였습니다. 그렇지 않나요?</p><p>하지만 곧 문제가 나타났습니다. 사용자는 다운로드한 뒤 한 번 쓰고 삭제했고, 7일 유지율은 5%뿐이었습니다. 그는 몇 가지 유료 기능을 만들었지만, 거의 아무도 돈을 내려고 하지 않았습니다. 더 낙담스러운 것은 Keep, Bohe Health, FitTime 같은 성숙한 제품들이 기능도 더 많고 콘텐츠도 더 좋다는 점이었습니다. 사용자가 왜 그의 APP으로 옮겨와야 할까요?</p><p>1년 뒤 샤오밍은 20만 위안을 손해 봤습니다.</p><p>그는 컴퓨터 앞에 앉아 처참한 백오피스 데이터를 보며 마음속에 단 하나의 질문만 남았습니다. 내 APP은 꽤 잘 만들었는데, 왜 아무도 쓰지 않을까? 더구나 왜 아무도 비용을 지불하지 않을까?</p><p>샤오밍의 실패는 기술이 부족해서도, 제품을 잘못 만들어서도 아닙니다. 솔직히 말해 그의 APP은 기능이 꽤 완전했고, 인터페이스도 꽤 보기 좋았습니다.</p><p><strong>문제는 출발점에 있었습니다.</strong></p><p>그는 가장 기본적인 질문을 한 번도 하지 않았습니다. 사용자가 정말 필요로 하는가?</p><p>그는 피트니스 APP 시장이 크고 Keep의 기업가치가 수십억이라고 보고, 이것이 좋은 기회라고 생각했습니다. 하지만 몇 가지를 제대로 파악하지 못했습니다. 사용자는 왜 또 다른 피트니스 APP이 필요할까요? Keep과 비교해 내 차별점은 무엇일까요? 사용자는 이것에 비용을 지불할 의향이 있을까요?</p><p><strong>방향이 틀리면, 깊이 들어갈수록 더 많이 틀립니다.</strong> 그는 1년을 들여 틀린 방향을 점점 더 완성도 있게 만들었고, 결과적으로 성공에서 점점 더 멀어졌습니다.</p><div class="tip custom-block"><p class="custom-block-title">이 장에서 우리가 할 일</p><p>이번 장에서는 샤오밍의 실패를 함께 되짚어 봅니다. 문제가 정확히 어디에서 생겼는지 보고, 진짜로 누군가 비용을 지불할 제품 방향을 함께 찾습니다.</p><p>우리는 세 단계로 진행합니다.</p><p><strong>1막: 진짜 요구 찾기</strong> - 먼저 어떤 요구에 사용자가 비용을 지불하는지 파악합니다.</p><p><strong>2막: 좋은 아이디어 파내기</strong> - 평범한 생각에서 가치 있는 비즈니스 기회를 발굴하는 법을 배웁니다.</p><p><strong>3막: AI 대화로 다듬기</strong> - AI를 사용해 생각을 실행 가능한 제품 방안으로 바꿉니다.</p></div><hr><h2 id="_1막-진짜-요구-찾기" tabindex="-1">1막: 진짜 요구 찾기 <a class="header-anchor" href="#_1막-진짜-요구-찾기" aria-label="Permalink to “1막: 진짜 요구 찾기”">​</a></h2><p>샤오밍은 매우 낙담했지만 포기하지 않았습니다. 그는 한 가지 문제를 되돌아보기 시작했습니다. 대체 어떤 요구에 사용자가 비용을 지불할까요?</p><h3 id="샤오밍의-혼란-왜-사용자는-비용을-지불하지-않을까" tabindex="-1">샤오밍의 혼란: 왜 사용자는 비용을 지불하지 않을까? <a class="header-anchor" href="#샤오밍의-혼란-왜-사용자는-비용을-지불하지-않을까" aria-label="Permalink to “샤오밍의 혼란: 왜 사용자는 비용을 지불하지 않을까?”">​</a></h3><p>그는 자신의 APP을 사용해 본 친구 몇 명을 찾아가 진짜 생각을 들어 보려고 했습니다.</p><p>친구 A가 말했습니다. “네 APP은 꽤 잘 만들었어. 그런데 나는 이미 Keep을 쓰고 있는데 왜 바꿔야 해?”</p><p>친구 B가 말했습니다. “매번 운동을 기록하라고 하는 게 너무 번거로워. 나는 기록하기 귀찮아.”</p><p>친구 C는 더 직접적으로 말했습니다. “무료 기능으로 충분한데 왜 돈을 내야 해?”</p><p>이 답변들은 샤오밍에게 문제가 어디에 있는지 갑자기 깨닫게 했습니다.</p><p><strong>첫 번째 문제: 사용자가 바꾸지 않는 이유는 기존 방안이 이미 충분히 좋기 때문입니다.</strong> Keep 같은 성숙한 제품은 기능이 이미 매우 완전하고, 사용자 습관도 형성되어 있으며, 이전 비용이 높습니다. 비슷한 제품 하나를 만든다고 해서 사용자가 왜 바꿔야 할까요?</p><p><strong>두 번째 문제: 사용자는 습관을 바꾸려 하지 않습니다.</strong> 운동을 기록하는 일은 사용자에게 너무 번거롭습니다. 어떤 제품이 사용자에게 3개 이상의 습관을 바꾸라고 요구하면 실패할 확률이 높습니다.</p><p><strong>세 번째 문제: 무료 대체재가 너무 많습니다.</strong> 기능이 너무 범용적이고 독특한 가치가 없으면, 사용자는 비용을 지불할 이유를 찾지 못합니다.</p><h3 id="진짜-요구란-무엇인가" tabindex="-1">진짜 요구란 무엇인가? <a class="header-anchor" href="#진짜-요구란-무엇인가" aria-label="Permalink to “진짜 요구란 무엇인가?”">​</a></h3><p>샤오밍은 사용자가 기꺼이 비용을 지불하는 성공 제품들을 연구하기 시작했습니다. 그는 공통점을 하나 발견했습니다. 이런 제품들이 해결하는 것은 “내가 유용하다고 느끼는” 요구가 아니라, 사용자가 비용을 지불하고, 행동을 바꾸고, 불편을 감수할 의지가 있는 요구였습니다.</p><p>다시 말해 <strong>진짜 요구는 사용자가 발로 투표해 드러낸 것이지, 제품 관리자가 머리로 상상해 낸 것이 아닙니다.</strong></p><h3 id="사례-사용자가-비용을-지불하게-하는-제품" tabindex="-1">사례: 사용자가 비용을 지불하게 하는 제품 <a class="header-anchor" href="#사례-사용자가-비용을-지불하게-하는-제품" aria-label="Permalink to “사례: 사용자가 비용을 지불하게 하는 제품”">​</a></h3><p>샤오밍은 성공 사례 몇 가지를 연구하며, 이들이 정확히 어떤 문제점을 붙잡았는지 알고 싶었습니다.</p><h4 id="meicai-작은-식당-사장이-잠을-잘-수-있게-하기" tabindex="-1">Meicai: 작은 식당 사장이 잠을 잘 수 있게 하기 <a class="header-anchor" href="#meicai-작은-식당-사장이-잠을-잘-수-있게-하기" aria-label="Permalink to “Meicai: 작은 식당 사장이 잠을 잘 수 있게 하기”">​</a></h4><p>겉으로 보면 Meicai가 하는 일은 간단합니다. 식당의 식재료 구매를 도와줍니다. 하지만 자세히 생각해 보면 식당 사장은 왜 이것을 사용할까요?</p><p>작은 식당 사장은 매일 새벽 4시에 일어나 도매시장에 가야 합니다. 매우 힘들고, 자주 바가지를 쓰기도 합니다. Meicai가 하는 일은 단순한 “식재료 이커머스”가 아니라 전체 공급망을 재구성하여 작은 식당 사장이 잠을 잘 수 있게 하는 것입니다.</p><p>문제점이 아플수록 지불 의향은 강해집니다. 절약되는 시간과 체력은 절약되는 식재료 값보다 더 가치 있습니다.</p><h4 id="샤오홍슈-선택-어려움-해결" tabindex="-1">샤오홍슈: 선택 어려움 해결 <a class="header-anchor" href="#샤오홍슈-선택-어려움-해결" aria-label="Permalink to “샤오홍슈: 선택 어려움 해결”">​</a></h4><p>겉으로 보면 샤오홍슈는 “해외 쇼핑 경험 공유”입니다. 하지만 사용자는 왜 시간을 들여 그 안의 노트를 볼까요?</p><p>상품이 너무 많을 때 사용자는 무엇이 살 만하고 무엇이 살 만하지 않은지 모릅니다. 자신을 대신해 선별해 주고, 시간을 아끼고, 함정을 피하게 도와줄 믿을 만한 사람이 필요합니다.</p><p>샤오홍슈가 해결하는 것은 사실 두 가지 깊은 문제점입니다. 선택 어려움과 신뢰 결핍입니다. 사용자는 “시간 절약”과 “실패 회피”에 기꺼이 비용을 지불합니다. 이것이 샤오홍슈가 성장할 수 있었던 이유입니다.</p><hr><p>이 사례들을 본 뒤 샤오밍은 중요한 발견을 했습니다.</p><p>사용자가 비용을 지불하는 것은 결코 “기능”이 아니라 “두려움 해결”과 “불안 제거”입니다. Meicai는 작은 식당 사장이 새벽 구매의 고됨을 두려워하는 문제를 해결하고, 샤오홍슈는 사용자가 잘못 살까 봐 두려워하는 문제를 해결합니다.</p><p><strong>두려움은 결제를 이끌고, 불안은 행동을 이끕니다.</strong></p><h3 id="요구의-세-층-문제점-만족점-가려운-지점" tabindex="-1">요구의 세 층: 문제점, 만족점, 가려운 지점 <a class="header-anchor" href="#요구의-세-층-문제점-만족점-가려운-지점" aria-label="Permalink to “요구의 세 층: 문제점, 만족점, 가려운 지점”">​</a></h3><p>샤오밍은 더 연구하면서 사용자의 요구를 세 가지 유형으로 나눌 수 있다는 것을 발견했습니다.</p><div class="tip custom-block"><p class="custom-block-title">문제점(Pain Point) - 두려움이 이끄는 것</p><p><strong>본질:</strong> 사용자가 지금 겪고 있으며 고통, 불안, 불편을 느끼게 하는 문제입니다. 해결하지 않으면 매우 괴롭고, 심지어 생존이나 안전을 위협할 수도 있습니다.</p><p><strong>예시:</strong></p><ul><li>당뇨병 환자가 탄수화물을 얼마나 먹으면 혈당이 급상승하는지 모름(두려움: 건강 위협)</li><li>작은 식당 사장이 새벽 4시에 일어나 도매시장에 감(두려움: 생존의 고됨)</li></ul><p><strong>핵심:</strong> 사용자는 이것에 비용을 지불할 의향이 있습니다. 해결하지 않으면 “너무 아프기” 때문입니다.</p></div><div class="tip custom-block"><p class="custom-block-title">만족점(Delight Point) - 즉시 만족</p><p><strong>본질:</strong> 사용자에게 어떤 요구가 있고, 그것이 즉시 충족되어 즉각적인 즐거움을 만드는 것입니다.</p><p><strong>예시:</strong></p><ul><li>배달 음식이 30분 안에 도착함(배고픔의 즉시 만족)</li><li>클릭 한 번으로 보기 좋은 PPT 생성(시간과 힘을 아끼는 만족감)</li></ul><p><strong>핵심:</strong> 사용자를 “기분 좋게” 만드는 것은 유지율의 핵심이지만, 단독 결제 포인트로는 약합니다.</p></div><div class="tip custom-block"><p class="custom-block-title">가려운 지점(Itch Point) - 가상의 자아</p><p><strong>본질:</strong> 사용자는 더 나아지고, 더 멋지고, 더 세련되고 싶어 하지만 필수는 아닙니다. 만족하면 기쁘지만, 만족하지 않아도 괜찮습니다.</p><p><strong>예시:</strong></p><ul><li>매일 물을 얼마나 마셨는지 기록하기(상상 속의 자기관리 생활)</li><li>AI로 사진에 예술 필터 추가하기(상상 속의 예술적 취향)</li></ul><p><strong>핵심:</strong> 사용자가 “가려운 지점”에 비용을 지불할 의향은 약합니다. 해결하지 않아도 괜찮기 때문입니다.</p></div><p>올바른 우선순위는 어떻게 봐야 할까요? 좋은 제안은 다음입니다. 문제점 &gt; 만족점 &gt; 가려운 지점</p><p>왜 그럴까요?</p><ol><li><strong>문제점은 생존 요구입니다:</strong> 해결하지 않으면 죽거나 매우 괴롭습니다. 사용자는 비용을 지불할 수밖에 없습니다. “진통제”입니다.</li><li><strong>만족점은 즉시 보상입니다:</strong> 사용자를 기분 좋게 만들면 사용자는 다시 옵니다. “중독 장치”입니다.</li><li><strong>가려운 지점은 욕망 충족입니다:</strong> 있어도 되고 없어도 되며, 가장 먼저 잘려 나가기 쉽습니다. “비타민” 또는 “사치품”입니다.</li></ol><p><strong>핵심 통찰:</strong> 많은 제품 관리자가 저지르는 실수는 가려운 지점 제품을 문제점 방식으로 팔려고 하는 것입니다.</p><p>예: “물 마시는 기록은 더 건강해지게 합니다.” 물을 마시는 것은 확실히 건강하지만, 기록하지 않는다고 건강하지 않은 것은 아닙니다. 이것은 가려운 지점을 문제점으로 포장하는 것이며, 사용자는 납득하지 않습니다.</p><h3 id="진짜-요구를-검증하는-5단계-방법" tabindex="-1">진짜 요구를 검증하는 5단계 방법 <a class="header-anchor" href="#진짜-요구를-검증하는-5단계-방법" aria-label="Permalink to “진짜 요구를 검증하는 5단계 방법”">​</a></h3><p>샤오밍은 생각했습니다. <strong>그렇다면 내게 아이디어가 하나 있을 때, 이것이 투자할 가치가 있는지 어떻게 빠르게 판단할 수 있을까?</strong></p><p>그는 제품 관리자가 자주 쓰는 5단계 판단법을 배웠습니다. 자세한 내용은 부록 A에 있습니다.</p><ol><li><p><strong>1단계: 실제 사용자와 직접 대화하고, 지금 어떻게 하고 있는지 이해하기</strong></p><p>목표 사용자 10명을 찾습니다. “지금은 이 문제를 어떻게 해결하고 있나요?”라고 묻습니다. 사용자가 이미 어떤 방법을 쓰고 있다면 문제가 실제로 존재한다는 뜻입니다. 사용자가 해결할 필요가 없다고 말한다면 진짜 요구가 아닐 수 있습니다.</p></li><li><p><strong>2단계: 사용자의 기존 대체 방안을 분석하고, 나의 장점 찾기</strong></p><p>사용자는 지금 다른 제품, Excel, 기억력, 또는 참고 견디기를 사용하고 있을 수 있습니다. 이 방안들의 단점이 무엇인지 파악해야 합니다. 당신의 제품이 그것들보다 훨씬 좋아야 사용자가 바꿀 의향이 생깁니다.</p></li><li><p><strong>3단계: 사용자가 제품에 돈을 낼 의향이 있는지 테스트하기</strong></p><p>사전 판매나 예약금을 받습니다. 예약금을 낼 의향이 있는 사용자 비율을 집계합니다. 돈을 빨리 벌수록 요구가 더 맞다는 뜻입니다.</p><ul><li>10% 초과: 요구가 진짜이며 투자할 가치가 있음</li><li>5%에서 10%: 요구는 존재하지만 다듬어야 함</li><li>5% 미만: 요구가 성립하지 않을 수 있음</li></ul></li><li><p><strong>4단계: 이 시장이 얼마나 크고 돈을 벌 수 있는지 추산하기</strong></p><p>세 숫자를 계산합니다. 목표 사용자 총수 × 지불 의향 × 객단가. 곱한 뒤 시장 규모를 얻습니다. 시장이 너무 작으면 만들 가치가 없을 수 있습니다.</p></li><li><p><strong>5단계: 제품에 어떤 해자가 있어 다른 사람이 베끼지 못하게 할 수 있는지 생각하기</strong></p><p>기술 난이도, 네트워크 효과, 브랜드, 비용 우위 같은 장벽을 고려합니다. 이것들은 장기 경쟁력을 유지하는 데 도움을 줍니다.</p></li></ol><p><strong>이번 막 소결: 샤오밍의 수확</strong></p><ol><li><p><strong>진짜 요구의 기준</strong></p><ul><li>가장 중요한 기준은 사용자가 비용을 지불할 의향이 있다는 것입니다.</li><li>사용자가 이를 위해 행동을 바꿀 의향이 있습니다.</li><li>해결 방안이 없으면 사용자가 큰 손실을 봅니다.</li></ul></li><li><p><strong>가짜 요구 피하기</strong></p><ul><li>가려운 지점은 문제점이 아니며, 진짜 요구로 보면 안 됩니다.</li><li>시장이 너무 작으면 비즈니스 모델을 지탱하기 어렵습니다.</li><li>해결 방안이 문제보다 더 복잡하면 사용자는 포기합니다.</li></ul></li><li><p><strong>우선순위 정렬</strong></p><ul><li>진짜 우선순위는 문제점 &gt; 만족점 &gt; 가려운 지점입니다.</li></ul></li></ol><p><strong>이번 막 산출물</strong></p><ul><li>진짜 요구가 무엇인지 이해했습니다.</li><li>요구의 세 층 분류인 문제점, 만족점, 가려운 지점을 익혔습니다.</li><li>5단계 판단법으로 요구의 진위를 검증하는 법을 배웠습니다.</li></ul><hr><h2 id="_2막-좋은-아이디어-파내기" tabindex="-1">2막: 좋은 아이디어 파내기 <a class="header-anchor" href="#_2막-좋은-아이디어-파내기" aria-label="Permalink to “2막: 좋은 아이디어 파내기”">​</a></h2><p>샤오밍은 이제 진짜 요구가 무엇인지 알게 되었지만, 여전히 어디에서 시작해야 할지 몰랐습니다. 허공에서 요구 하나를 상상해 낼 수는 없으니까요.</p><p>그는 자신에게 가장 익숙한 것에서 시작하기로 했습니다. 주변 사람과 주변 일입니다.</p><h3 id="자신에서-출발하기-샤오밍의-누나" tabindex="-1">자신에서 출발하기: 샤오밍의 누나 <a class="header-anchor" href="#자신에서-출발하기-샤오밍의-누나" aria-label="Permalink to “자신에서 출발하기: 샤오밍의 누나”">​</a></h3><p>샤오밍은 누나를 떠올렸습니다. 누나는 막 아이를 낳았고, 늘 운동할 시간이 없다고 불평했습니다. 배에 붙은 살이 빠지지 않고, 전체적으로 매우 불안해했습니다.</p><p>어느 날 샤오밍이 물었습니다. “지금 운동 문제는 어떻게 해결하고 있어?”</p><p>누나는 한숨을 쉬며 말했습니다. “Keep 따라 하긴 하는데, 그 동작들이 산후 몸에 맞지 않아. 하고 나면 허리가 더 아파. 헬스장? 아이 봐줄 사람이 없어. 개인 트레이너? 한 수업에 300-500위안이라 너무 비싸. 혼자 대충 하자니 다칠까 봐 무서워.”</p><p>샤오밍은 듣고 나서 이것이 찾고 있던 진짜 요구일지도 모른다고 느꼈습니다.</p><p>누나의 어려움은 사실 매우 구체적입니다. 시간은 조각나 있고, 아기를 돌봐야 해서 운동할 온전한 시간이 없습니다. 몸에는 제한이 있습니다. 복직근 이개, 골반저근 이완 때문에 격한 운동을 할 수 없습니다. 심리적으로 매우 불안합니다. 몸매가 변했고, 남편이 싫어할까 걱정하며, 사회적으로 자신감이 떨어집니다. 정보도 너무 혼란스럽습니다. 온라인 정보가 너무 많아 어떤 운동이 산후에 맞는지 모릅니다. 또한 고립감도 있습니다. 자신의 처지를 이해해 주는 사람이 없고 동료 지원이 부족합니다.</p><p>이것들은 모두 진짜 문제점입니다. “있으면 좋겠다” 수준의 가려운 지점이 아닙니다.</p><hr><h3 id="가로로-나누기-서로-다른-사람군의-요구" tabindex="-1">가로로 나누기: 서로 다른 사람군의 요구 <a class="header-anchor" href="#가로로-나누기-서로-다른-사람군의-요구" aria-label="Permalink to “가로로 나누기: 서로 다른 사람군의 요구”">​</a></h3><p>샤오밍은 “피트니스 APP”이라는 생각이 너무 넓다는 것을 깨달았습니다. 그는 모든 사람이 운동하도록 돕고 싶었지만, 문제는 모든 사람의 요구가 다르다는 점입니다.</p><p>그는 “운동하고 싶은 사람”을 몇 가지 유형으로 가로로 나누었습니다. 자세한 방법은 부록 B에 있습니다.</p><p>근육을 키우려는 사람은 단백질 섭취를 정확히 계산해야 하지만 직접 기록하기가 너무 번거롭습니다. 이들의 지불 의향은 높고 효율을 추구합니다. 당뇨병 환자는 탄수화물을 엄격히 통제해야 하지만 외식할 때 추산하기 어렵습니다. 이것은 필수 요구이며, 비용을 지불할 의향이 있고 재구매율도 높습니다. 산후 엄마는 몸매 회복을 원하지만 계산할 시간이 없고, 간단한 방안이 필요하며, 시간에 민감하고, 원스톱 서비스가 필요합니다. 배달 음식에 의존하는 사람은 매일 배달 음식을 먹으며 얼마나 많은 열량을 먹었는지 모릅니다. 고빈도 장면이지만 지불 의향은 중간입니다. 대학원 입시생은 효율적인 학습 도구가 필요하지만 무엇을 써야 할지 모릅니다. 필수 요구이지만 객단가는 낮습니다.</p><p>샤오밍은 “산후 엄마”라는 사람군을 선택했습니다. 왜일까요?</p><p>먼저 그는 사용자와 가까웠습니다. 누나가 산후 엄마였고, 이 집단의 문제점을 자연스럽게 이해했습니다. 둘째, 문제점이 매우 아픕니다. 산후 회복의 불안은 진짜이며, “있으면 좋다” 수준의 가려운 지점이 아닙니다. 셋째, 지불 의향이 강합니다. 엄마들은 몸매 회복을 위해 돈을 쓸 의향이 있습니다. 넷째, 경쟁이 상대적으로 치열하지 않습니다. 시장에는 산후 엄마를 전문적으로 겨냥한 제품이 많지 않습니다.</p><div class="tip custom-block"><p class="custom-block-title">제품 관리자의 나누기 논리</p><p>왜 사람군을 나누는 것이 이렇게 중요할까요?</p><p>범용 도구는 이기기 어렵기 때문입니다. 대형 플랫폼은 이미 “범용” 시장을 차지했고, 기능에서 그것들을 넘어서기는 어렵습니다. 세분화된 사람군의 요구는 더 아픕니다. 산후 엄마의 운동 요구는 필수 요구이고, 일반 운동자는 “있어도 되는” 수준입니다. 작은 집단 하나를 잘 서비스하는 것이 모든 사람을 만족시키려는 것보다 입소문을 만들기 쉽습니다. 세분화된 사람군의 문제점은 더 구체적이고, 해결 방안에 비용을 지불할 의향도 더 강합니다.</p></div><hr><h3 id="세로로-깊게-파기-완전한-사용자-장면" tabindex="-1">세로로 깊게 파기: 완전한 사용자 장면 <a class="header-anchor" href="#세로로-깊게-파기-완전한-사용자-장면" aria-label="Permalink to “세로로 깊게 파기: 완전한 사용자 장면”">​</a></h3><p>사람군을 찾은 뒤 샤오밍은 “산후 운동”이라는 단일 기능에 머물지 않았습니다. 그는 사용자의 완전한 장면을 더 깊게 이해하고 싶었습니다. 자세한 방법은 부록 C에 있습니다.</p><p>그는 누나의 하루 생활을 관찰했습니다.</p><p>아침 6시, 아기가 막 잠들었고 누나는 30분의 여유가 있었습니다. 운동하고 싶었지만 아기를 깨울까 봐 걱정했고, 어떤 동작이 안전한지도 몰랐습니다.</p><p>오전 10시, 누나는 아기를 안고 재우고 있었고 허리가 매우 아팠습니다. 몇 가지 회복 운동을 하고 싶었지만 손이 비어 있지 않았습니다.</p><p>오후 3시, 아기가 자고 누나는 운동하고 싶었습니다. 하지만 몸이 너무 피곤했고, 아직 운동해도 되는지 몰랐습니다.</p><p>밤 8시, 누나는 드디어 시간이 생겼지만 매우 불안했습니다. 거울 속의 자신을 보며 인생이 끝난 것 같다고 느끼고, 예전 사진을 넘겨 보며 몰래 울었습니다.</p><p>샤오밍은 누나의 문제점이 “운동 수업이 없음”이 아니라 “산후 회복에 대한 두려움과 불안”이라는 것을 발견했습니다.</p><hr><div class="info custom-block"><p class="custom-block-title">제품 관리자의 장면 사고</p><p>많은 사람은 문제점이 기능 요구라고 생각하지만, 사실 그렇지 않습니다. 문제점은 장면 속의 감정과 지불 의향이 더해진 것입니다.</p><p>산후 엄마가 거울 속 변한 몸매를 마주할 때, 진짜 문제점은 “어떻게 운동해야 하는지 모름”이 아닙니다. 두려움입니다. 몸이 잘 회복되지 않아 후유증이 남을까 걱정합니다. 불안입니다. 거울 속 자신을 보며 인생이 끝난 것처럼 느낍니다. 무력감입니다. 어디서부터 시작해야 할지 모르고 지도해 줄 사람도 없습니다. 고립감입니다. 다른 사람은 쉽게 출산하는 것 같은데 나만 이렇게 오래 회복해야 한다고 느낍니다.</p><p>좋은 제품 설계는 기능뿐 아니라 감정을 해결해야 합니다. 감정 뒤에는 사용자의 지불 동기가 있습니다.</p></div><hr><h3 id="가치-재구성-피트니스-app-에서-산후-엄마-회복-어시스턴트-로" tabindex="-1">가치 재구성: “피트니스 APP”에서 “산후 엄마 회복 어시스턴트”로 <a class="header-anchor" href="#가치-재구성-피트니스-app-에서-산후-엄마-회복-어시스턴트-로" aria-label="Permalink to “가치 재구성: “피트니스 APP”에서 “산후 엄마 회복 어시스턴트”로”">​</a></h3><p>위 분석을 바탕으로 샤오밍은 이 제품을 다시 설계했습니다.</p><div class="tip custom-block"><p class="custom-block-title">재구성된 제품 개념: “산후 엄마 회복 어시스턴트”</p><p><strong>핵심 포지셔닝:</strong> 단순한 피트니스 도구가 아니라 산후 엄마의 “전용 회복 코치 + 심리 지원자”</p><p><strong>핵심 기능:</strong></p><ol><li><p><strong>조각 시간 훈련:</strong></p><ul><li>매번 10-15분만 필요</li><li>아기가 잘 때도 운동 가능</li><li>“아기를 안고도 할 수 있는” 동작 제공</li></ul></li><li><p><strong>산후 전용 수업:</strong></p><ul><li>산후 단계별 분류(0-3개월, 3-6개월, 6개월 이상)</li><li>복직근 이개, 골반저근 회복을 겨냥한 전문 훈련</li><li>각 동작마다 “산후 주의사항” 안내</li></ul></li><li><p><strong>AI 동작 교정:</strong></p><ul><li>휴대폰 카메라로 동작 인식</li><li>“무릎이 너무 굽었어요”, “등을 곧게 펴세요” 같은 실시간 안내</li><li>잘못된 동작으로 몸을 다치는 것을 방지</li></ul></li><li><p><strong>심리 지원 커뮤니티:</strong></p><ul><li>산후 엄마만 있는 비공개 커뮤니티</li><li>회복 과정을 공유하고 서로 격려</li><li>전문 심리 상담사가 입주</li></ul></li><li><p><strong>개인화 방안:</strong></p><ul><li>출산 방식(자연분만/제왕절개), 몸 상태에 따라 맞춤화</li><li>수유기의 특수 요구 고려</li></ul></li></ol><p><strong>비즈니스 모델:</strong></p><ul><li>기본 수업 무료</li><li>고급 수업: 월 99위안(AI 동작 교정, 전용 방안 포함)</li><li>1:1 개인 코칭: 월 299위안(온라인 지도)</li><li>커뮤니티 회원: 연 199위안(심리 지원, 전문가 Q&amp;A 포함)</li></ul><p><strong>경쟁 장벽:</strong></p><ul><li>전문성: 산후 회복 기관과 협력하고 의학적 근거를 갖춤</li><li>커뮤니티 점착성: 산후 엄마의 감정 연결이 강함</li><li>데이터 축적: 사용자 신체 데이터가 많을수록 방안이 더 정확해짐</li></ul><p><strong>시장 규모:</strong></p><ul><li>중국의 연간 신생아 약 1,000만 명</li><li>산후 회복 시장 약 500억 위안</li><li>목표: 산후 엄마의 1% 서비스 = 사용자 10만 명</li><li>ARPU(사용자당 평균 매출): 연 500위안</li><li>잠재 매출: 연 5,000만 위안</li></ul></div><p>원래 idea와 재구성 후 개념을 비교해 봅니다.</p><table tabindex="0"><thead><tr><th>차원</th><th>원래 생각</th><th>재구성 후</th></tr></thead><tbody><tr><td>목표 사용자</td><td>모든 운동 인구(크고 넓음)</td><td>산후 엄마(정확함)</td></tr><tr><td>해결 문제점</td><td>훈련 기록(가려운 지점)</td><td>산후 회복 불안(문제점)</td></tr><tr><td>경쟁 장벽</td><td>기술(복제 쉬움)</td><td>전문성 + 커뮤니티 + 데이터</td></tr><tr><td>지불 의향</td><td>낮음(무료 대체재 많음)</td><td>높음(필수 요구 + 감정 가치)</td></tr><tr><td>확장 공간</td><td>제한적</td><td>임신기, 임신 준비기로 확장 가능</td></tr></tbody></table><p><strong>이것이 “하나의 기능”에서 “누군가 비용을 지불할 제품”으로 진화하는 과정입니다.</strong></p><hr><h3 id="더-많은-예시-평범한-idea에서-좋은-아이디어까지" tabindex="-1">더 많은 예시: 평범한 idea에서 좋은 아이디어까지 <a class="header-anchor" href="#더-많은-예시-평범한-idea에서-좋은-아이디어까지" aria-label="Permalink to “더 많은 예시: 평범한 idea에서 좋은 아이디어까지”">​</a></h3><p>샤오밍은 이 방법이 매우 유용하다고 느꼈습니다. 그는 같은 방법으로 몇 가지 다른 예시도 분석해 보며 이 방법이 일반적으로 통하는지 확인했습니다. 자세한 사례는 부록 D에 있습니다.</p><h4 id="예시-1-칼로리-측정-에서-당뇨인이-안심하고-먹기-까지" tabindex="-1">예시 1: “칼로리 측정”에서 “당뇨인이 안심하고 먹기”까지 <a class="header-anchor" href="#예시-1-칼로리-측정-에서-당뇨인이-안심하고-먹기-까지" aria-label="Permalink to “예시 1: “칼로리 측정”에서 “당뇨인이 안심하고 먹기”까지”">​</a></h4><p>평범한 생각은 사진으로 음식 열량을 인식해 다이어트하는 사람이 식단을 통제하도록 돕는 것입니다. 하지만 문제는 이미 Bohe Health, MyFitnessPal 같은 성숙한 제품이 있다는 점입니다.</p><p>샤오밍은 가로로 나눠 보다가 당뇨병 환자라는 사람군이 흥미롭다는 것을 발견했습니다. 이들은 탄수화물을 엄격히 통제해야 하지만 외식할 때 추산하기가 어렵습니다. 이들의 장면을 세로로 깊게 파 보면, 식사 전에는 이 음식을 먹어도 되는지 몰라 혈당이 급상승할까 걱정하고, 식사 중에는 “이미 탄수화물을 얼마나 먹었는지” 실시간으로 안내받아야 하며, 식사 후에는 혈당 변화를 기록해 식단과의 관계를 봐야 합니다.</p><p>재구성된 제품은 “당뇨인이 안심하고 먹기”이고, 포지셔닝은 당뇨병 환자의 “식단 안전 어시스턴트”입니다.</p><hr><h4 id="예시-2-뉴스-어시스턴트-에서-투자-리서치-정보관-까지" tabindex="-1">예시 2: “뉴스 어시스턴트”에서 “투자 리서치 정보관”까지 <a class="header-anchor" href="#예시-2-뉴스-어시스턴트-에서-투자-리서치-정보관-까지" aria-label="Permalink to “예시 2: “뉴스 어시스턴트”에서 “투자 리서치 정보관”까지”">​</a></h4><p>평범한 생각은 여러 플랫폼의 뉴스를 모아 하나씩 열 필요를 없애는 것입니다. 하지만 Toutiao, Tencent News 등은 이미 잘하고 있습니다.</p><p>샤오밍은 가로로 나눈 뒤 금융 애널리스트라는 사람군에게 특수 요구가 있음을 발견했습니다. 이들은 특정 산업 동향을 추적해야 하지만 정보가 너무 흩어져 있습니다. 이들의 장면을 세로로 깊게 파 보면, 아침에는 overnight 미국 주식 동향과 환율 변화를 보고, 오전에는 보유 회사의 공시와 산업 뉴스를 추적하며, 오후에는 잠재 투자 대상을 연구하기 위해 많은 산업 정보를 필요로 합니다.</p><p>재구성된 제품은 “투자 리서치 정보관”이고, 포지셔닝은 금융 종사자의 “정보 레이더와 의사결정 어시스턴트”입니다.</p><hr><h4 id="예시-3-캠퍼스-중고-플랫폼-에서-졸업-정리-어시스턴트-까지" tabindex="-1">예시 3: “캠퍼스 중고 플랫폼”에서 “졸업 정리 어시스턴트”까지 <a class="header-anchor" href="#예시-3-캠퍼스-중고-플랫폼-에서-졸업-정리-어시스턴트-까지" aria-label="Permalink to “예시 3: “캠퍼스 중고 플랫폼”에서 “졸업 정리 어시스턴트”까지”">​</a></h4><p>평범한 생각은 캠퍼스 중고 거래 플랫폼입니다. 하지만 Xianyu, Zhuanzhuan은 이미 잘하고 있습니다.</p><p>샤오밍은 가로로 나눈 뒤 졸업생이라는 사람군에게 특수 요구가 있음을 발견했습니다. 물건이 너무 많아 하나씩 팔기 너무 번거롭습니다. 이들의 장면을 세로로 깊게 파 보면, 졸업 전 일주일 안에 학교를 떠나야 해서 천천히 팔 시간이 없고, 누가 내 물건을 필요로 하는지도 모르며, 가격 흥정, 전달, 수금이 너무 번거롭습니다.</p><p>재구성된 제품은 “졸업 정리 어시스턴트”이고, 포지셔닝은 졸업생의 “퇴교 자산 매니저”입니다.</p><hr><h3 id="이번-막-소결-샤오밍의-수확" tabindex="-1">이번 막 소결: 샤오밍의 수확 <a class="header-anchor" href="#이번-막-소결-샤오밍의-수확" aria-label="Permalink to “이번 막 소결: 샤오밍의 수확”">​</a></h3><p>2막을 통해 샤오밍은 다음을 이해했습니다.</p><p><strong>1. 자신에서 출발하기</strong></p><ul><li>당신 자신이 사용자라면, 그 집단의 문제점을 자연스럽게 이해합니다.</li><li>취미는 가장 좋은 출발점이고, 열정은 가장 좋은 동력입니다.</li></ul><p><strong>2. 사람군을 가로로 나누기</strong></p><ul><li>“모든 사람”을 서비스하려 하지 말고, “가장 아픈 사람군”을 찾습니다.</li><li>더 세분화할수록 더 많은 기회가 있고, 사용자의 지불 의향도 더 강합니다.</li></ul><p><strong>3. 장면을 세로로 깊게 파기</strong></p><ul><li>사용자의 완전한 여정을 설명합니다. 사용 전, 사용 중, 사용 후.</li><li>감정 접점을 찾습니다. 두려움, 불안, 무력감, 고립감...</li></ul><p><strong>4. 가치 재구성</strong></p><ul><li>“기능”에서 “해결 방안”으로 업그레이드합니다.</li><li>“도구”에서 “어시스턴트 / 매니저 / 파트너”로 업그레이드합니다.</li></ul><hr><p>📦 <strong>이번 막 산출물:</strong></p><ul><li>정확한 목표 사용자(산후 엄마)를 찾았습니다.</li><li>사용자의 완전한 장면과 진짜 감정을 이해했습니다.</li><li>제품 개념을 재구성했고, 명확한 차별화 포지셔닝을 갖게 되었습니다.</li></ul><hr><h2 id="_3막-ai-대화로-다듬기" tabindex="-1">3막: AI 대화로 다듬기 <a class="header-anchor" href="#_3막-ai-대화로-다듬기" aria-label="Permalink to “3막: AI 대화로 다듬기”">​</a></h2><p>샤오밍은 이제 명확한 제품 방향을 갖게 되었습니다. 산후 엄마 회복 어시스턴트입니다. 하지만 여전히 구체적으로 어떻게 만들지, 어디서 시작할지, 기술 구현 난이도가 얼마나 될지 몰랐습니다.</p><p>그는 AI를 사용해 제품 개념을 다듬고, 생각을 실행 가능한 계획으로 바꾸기로 했습니다.</p><h3 id="첫-번째-라운드-원래-생각-던지기" tabindex="-1">첫 번째 라운드: 원래 생각 던지기 <a class="header-anchor" href="#첫-번째-라운드-원래-생각-던지기" aria-label="Permalink to “첫 번째 라운드: 원래 생각 던지기”">​</a></h3><p>샤오밍은 자신의 생각을 AI에게 말했습니다. “산후 엄마 회복 어시스턴트 APP을 만들고 싶어. 산후 엄마가 몸매를 회복하도록 도와주는 앱이야. 그런데 기술 구현 난이도가 걱정돼. 특히 AI 동작 교정 기능은 혼자 할 수 있을까?”</p><hr><h3 id="두-번째-라운드-ai가-mvp-계획을-돕기" tabindex="-1">두 번째 라운드: AI가 MVP 계획을 돕기 <a class="header-anchor" href="#두-번째-라운드-ai가-mvp-계획을-돕기" aria-label="Permalink to “두 번째 라운드: AI가 MVP 계획을 돕기”">​</a></h3><p>AI가 답했습니다. “좋은 질문입니다! MVP(최소 기능 제품) 계획을 해 봅시다.”</p><p>AI는 세 단계로 나누어 만들 것을 제안했습니다. 첫 번째 단계는 1-2개월이며 목표는 요구 검증입니다. APP을 만들지 말고 먼저 WeChat 미니프로그램을 만들고, 산후 전용 수업(영상)과 체크인 커뮤니티만 제공합니다. 동작 지도는 사람이 제공합니다. 사용자가 영상을 업로드하면 코치가 답변합니다. 목표는 산후 엄마가 비용을 지불할 의향이 있는지 검증하는 것입니다.</p><p>두 번째 단계는 3-6개월입니다. 첫 단계가 성공적으로 검증되면 핵심 기능을 추가합니다. AI 동작 교정을 개발하며, Baidu 인체 인식 같은 기존 SDK를 사용할 수 있습니다. 개인화 방안을 추가하고 커뮤니티 기능을 최적화합니다.</p><p>세 번째 단계는 6-12개월이며 규모화입니다. 독립 APP을 개발하고, 산후 회복 기관과 협력하며, 임신기와 임신 준비기로 확장합니다.</p><p>기술 구현에 대해서 AI는 AI 동작 교정에 Baidu, Tencent의 API 같은 기존 AI 능력을 사용하라고 제안했습니다. 처음부터 개발할 필요가 없어서 비용을 낮출 수 있습니다. 초기에는 사람 + AI 혼합 모드를 사용하고, 점차 전환합니다.</p><p>시작 비용 측면에서 미니프로그램 개발은 1-2만 위안(외주) 또는 AI IDE로 직접 만들 수 있습니다. 콘텐츠 제작은 산후 회복 코치와 협력하고, 홍보는 엄마 커뮤니티와 샤오홍슈에서 시작합니다.</p><p>검증 지표는 첫 달 사용자 100명, 10% 유료 전환율입니다. 도달하면 요구가 진짜라는 뜻이므로 계속 투자합니다. 도달하지 못하면 방향을 즉시 조정합니다.</p><hr><h3 id="세-번째-라운드-샤오밍이-걱정을-제기하기" tabindex="-1">세 번째 라운드: 샤오밍이 걱정을 제기하기 <a class="header-anchor" href="#세-번째-라운드-샤오밍이-걱정을-제기하기" aria-label="Permalink to “세 번째 라운드: 샤오밍이 걱정을 제기하기”">​</a></h3><p>샤오밍은 생각한 뒤 다시 물었습니다. “콘텐츠 제작이 걱정돼. 산후 회복 수업은 전문 지도가 필요한데, 나는 의학 배경이 없어. 수업 품질을 어떻게 보장하지?”</p><hr><h3 id="네-번째-라운드-ai가-해결-방안을-제시하기" tabindex="-1">네 번째 라운드: AI가 해결 방안을 제시하기 <a class="header-anchor" href="#네-번째-라운드-ai가-해결-방안을-제시하기" aria-label="Permalink to “네 번째 라운드: AI가 해결 방안을 제시하기”">​</a></h3><p>AI가 답했습니다. “이것은 많은 기술형 창업자가 걱정하는 부분이지만 해결 방안이 있습니다.”</p><p>방안 1은 전문가와 협력하는 것입니다. 산후 회복 코치나 병원 영양과 의사와 협력합니다. 당신은 기술과 제품을 제공하고, 그들은 전문 콘텐츠를 제공합니다. 수익 배분 방식을 사용할 수 있습니다.</p><p>방안 2는 기존 고품질 콘텐츠를 통합하는 것입니다. 초기에는 YouTube나 Bilibili의 공개 산후 회복 영상 같은 것을 사용할 수 있습니다. 직접 콘텐츠 검토와 정리를 하고, 이후에 오리지널 콘텐츠를 제작합니다.</p><p>방안 3은 사용자 생성 콘텐츠입니다. 경험 있는 엄마들이 자신의 회복 방법을 공유하도록 장려하고, 커뮤니티 투표 방식으로 고품질 콘텐츠를 선별하며, 점차 콘텐츠 생태계를 구축합니다.</p><p>AI는 먼저 방안 1을 사용하라고 제안했습니다. 구체적인 조작은 다음입니다. 산후 회복 코치 2-3명을 찾아 협력 논의를 합니다. 당신은 제품을 개발하고, 그들은 수업을 제공합니다. 수익은 분배합니다. 당신이 70%, 그들이 30%를 가져갑니다. 이렇게 하면 콘텐츠 품질을 보장하면서 비용도 낮출 수 있습니다. 초기 수업 제작 비용은 0위안입니다. 수익 배분 방식을 쓰면 개발 시간과 홍보 비용만 투입하면 됩니다.</p><p><strong>나의 제안: 먼저 방안 1 사용하기</strong></p><p>구체적인 조작:</p><ol><li>산후 회복 코치 2-3명을 찾기</li><li>협력 논의하기: 당신은 제품을 개발하고, 그들은 수업을 제공</li><li>수익 배분: 당신 70%, 코치 30%</li><li>이렇게 하면 콘텐츠 품질을 보장하면서 비용도 낮출 수 있음</li></ol><p><strong>초기 비용:</strong></p><ul><li>수업 제작: 0위안(수익 배분 방식 사용)</li><li>당신은 개발 시간과 홍보 비용만 투입하면 됨</li></ul><p>:::</p><hr><h3 id="다섯-번째-라운드-샤오밍이-홍보-문제를-묻기" tabindex="-1">다섯 번째 라운드: 샤오밍이 홍보 문제를 묻기 <a class="header-anchor" href="#다섯-번째-라운드-샤오밍이-홍보-문제를-묻기" aria-label="Permalink to “다섯 번째 라운드: 샤오밍이 홍보 문제를 묻기”">​</a></h3><p>샤오밍에게는 마지막 걱정이 남았습니다. “홍보 비용이 높지 않을까? 산후 엄마라는 집단을 어떻게 찾지?”</p><hr><h3 id="여섯-번째-라운드-ai가-홍보-전략을-제공하기" tabindex="-1">여섯 번째 라운드: AI가 홍보 전략을 제공하기 <a class="header-anchor" href="#여섯-번째-라운드-ai가-홍보-전략을-제공하기" aria-label="Permalink to “여섯 번째 라운드: AI가 홍보 전략을 제공하기”">​</a></h3><p>AI가 답했습니다. “산후 엄마라는 집단은 사실 찾기 매우 쉽고, 홍보 비용도 낮출 수 있습니다.”</p><p>가장 추천하는 것은 샤오홍슈입니다. “산후 회복”, “복직근 이개” 같은 키워드를 검색해 관련 블로거를 찾고, 개인 메시지로 협력합니다. “1개월 무료 체험” 방식으로 홍보를 교환하면 비용은 거의 0입니다.</p><p>그다음은 엄마 커뮤니티입니다. WeChat 그룹, QQ 그룹을 검색하고 “산후 회복 경험 공유”라는 명목으로 들어갑니다. 직접 광고하지 말고 실용적인 콘텐츠를 공유하며 신뢰를 점차 쌓습니다.</p><p>또한 병원 산부인과와 협력해 무료 산후 회복 지도를 제공하고 병원에서 홍보 전단을 배포할 수 있습니다. 비용은 인쇄비 몇백 위안입니다. 또는 모자용품점과 협력해 홍보물을 배치하고, 모자용품 구매 시 체험 카드를 증정할 수 있습니다. 비용은 체험 카드 제작비입니다.</p><p>검증 지표는 다음입니다. 첫 달 사용자 100명, 유료 사용자 10명(10% 전환율), 총 홍보 비용 1,000위안 미만, 고객 획득 비용 1인당 10위안 미만. 이 지표에 도달하면 요구가 진짜라는 뜻이며 계속 투자할 수 있습니다.</p><hr><h3 id="최종-샤오밍에게-명확한-계획이-생기다" tabindex="-1">최종: 샤오밍에게 명확한 계획이 생기다 <a class="header-anchor" href="#최종-샤오밍에게-명확한-계획이-생기다" aria-label="Permalink to “최종: 샤오밍에게 명확한 계획이 생기다”">​</a></h3><p>6번의 대화 후 샤오밍은 마침내 명확한 계획을 갖게 되었습니다.</p><p>첫 번째 단계는 1-2개월입니다. WeChat 미니프로그램을 만들고, 산후 회복 코치 2-3명과 협력합니다(수익 배분 방식). 산후 전용 수업(영상)과 체크인 커뮤니티만 제공하고, 동작 지도는 사람이 제공합니다. 목표는 사용자 100명과 10% 유료 전환율입니다.</p><p>두 번째 단계는 3-6개월입니다. 첫 단계 검증이 성공하면 계속 투자합니다. AI 동작 교정 기능을 추가하고, 개인화 방안을 추가하며, 커뮤니티 기능을 최적화합니다.</p><p>세 번째 단계는 6-12개월입니다. 독립 APP을 개발하고, 산후 회복 기관과 협력하며, 임신기와 임신 준비기로 확장합니다.</p><p>시작 비용은 매우 낮습니다. 개발은 AI IDE로 직접 합니다(0위안). 콘텐츠는 코치와 수익을 나눕니다(초기 0위안). 홍보는 샤오홍슈와 엄마 커뮤니티를 사용합니다(1,000위안 미만). 총 비용은 1,000위안 미만입니다.</p><hr><h3 id="ai-대화로-다듬는-5단계-방법" tabindex="-1">AI 대화로 다듬는 5단계 방법 <a class="header-anchor" href="#ai-대화로-다듬는-5단계-방법" aria-label="Permalink to “AI 대화로 다듬는 5단계 방법”">​</a></h3><p>이 사례를 통해 샤오밍은 AI와 대화하는 표준 흐름을 정리했습니다. 자세한 내용은 부록 E에 있습니다.</p><p><strong>1단계: 원래 생각 던지기.</strong> 초기 생각을 설명합니다. 거칠어도 괜찮습니다. 경쟁이 치열하다거나 차별화 방법을 모르겠다는 걱정도 AI에게 말합니다.</p><p><strong>2단계: AI에게 MVP 계획을 도와달라고 하기.</strong> 최소 기능 제품은 어떤 기능을 포함해야 할까요? 몇 단계로 나눌까요? 각 단계의 목표는 무엇일까요? 기술 구현 난이도는 높은가요?</p><p><strong>3단계: 걱정 제기하기.</strong> 기술 구현 난이도, 콘텐츠 제작 비용, 홍보 비용, 사용자 획득 난이도 등 걱정을 모두 AI에게 말합니다.</p><p><strong>4단계: AI에게 해결 방안을 요청하기.</strong> 당신의 걱정에 대해 AI가 구체적인 제안을 줍니다. 여러 방안을 비교하고 최적안을 선택합니다. 비용도 추산합니다.</p><p><strong>5단계: 최종 계획 확인하기.</strong> 명확한 실행 계획을 정리하고 검증 지표를 설정합니다. 도달하지 못하면 즉시 방향을 조정합니다.</p><p><strong>프롬프트 템플릿:</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[제품 개념]을 만들고 싶습니다.</span></span>
<span class="line"><span>하지만 [나의 걱정]이 걱정됩니다.</span></span>
<span class="line"><span>다음을 도와주세요:</span></span>
<span class="line"><span>1. MVP를 계획하기</span></span>
<span class="line"><span>2. 구체적인 기술 구현 제안 제시하기</span></span>
<span class="line"><span>3. 비용 추산하기</span></span>
<span class="line"><span>4. 검증 지표 설정하기</span></span></code></pre></div><hr><h3 id="이번-막-소결-샤오밍의-수확-1" tabindex="-1">이번 막 소결: 샤오밍의 수확 <a class="header-anchor" href="#이번-막-소결-샤오밍의-수확-1" aria-label="Permalink to “이번 막 소결: 샤오밍의 수확”">​</a></h3><p>3막을 통해 샤오밍은 세 가지를 이해했습니다.</p><p><strong>첫째, AI 대화로 제품 개념을 다듬기.</strong> 한 번의 대화로 완벽한 답을 기대하지 말고 여러 라운드로 반복합니다. 당신의 관찰, 경험, 주변 사람의 피드백을 AI에게 알려 줍니다. AI의 제안이 합리적이지 않다면 즉시 지적합니다. 마지막에는 반드시 구체적인 실행 계획으로 내려와야 합니다.</p><p><strong>둘째, MVP의 핵심 원칙.</strong> 최소화합니다. 가장 핵심 기능만 만듭니다. 검증 가능해야 합니다. 요구가 진짜인지 빠르게 검증할 수 있어야 합니다. 낮은 비용으로 검증합니다.</p><p><strong>셋째, 검증 지표.</strong> 유료 전환율이 10%보다 크면 요구가 진짜이며 투자할 가치가 있습니다. 유료 전환율이 5-10%이면 요구는 존재하지만 다듬어야 합니다. 유료 전환율이 5%보다 낮으면 요구가 성립하지 않으므로 즉시 조정해야 합니다.</p><hr><p>📦 <strong>이번 장 산출물:</strong></p><ul><li>명확한 MVP 계획이 생겼습니다.</li><li>기술 구현 경로를 알게 되었습니다.</li><li>검증 지표를 설정했습니다.</li></ul><hr><h2 id="종장-당신의-행동" tabindex="-1">종장: 당신의 행동 <a class="header-anchor" href="#종장-당신의-행동" aria-label="Permalink to “종장: 당신의 행동”">​</a></h2><h3 id="기억-공식" tabindex="-1">기억 공식 <a class="header-anchor" href="#기억-공식" aria-label="Permalink to “기억 공식”">​</a></h3><p><strong>한 사람 한 일 한 진입점, 가로로 나누고 세로로 파서 문제점을 찾고, AI 대화로 개념을 다듬고, 5단계 검증 후 시작하라</strong></p><p><strong>설명:</strong></p><ul><li><strong>한 사람:</strong> 당신 자신에서 출발합니다. 당신은 그 집단을 자연스럽게 이해합니다.</li><li><strong>한 일:</strong> 하나의 구체적인 일에 집중합니다. 욕심내지 않습니다.</li><li><strong>한 진입점:</strong> 진입점을 찾습니다. 더 세분화할수록 좋습니다.</li><li><strong>가로 나누기:</strong> 사람군을 가로로 나누어 지불 의향이 가장 강한 사용자를 찾습니다.</li><li><strong>세로 파기:</strong> 장면을 세로로 깊게 파서 사용자의 완전한 여정을 이해합니다.</li><li><strong>AI 대화:</strong> AI 대화로 제품 개념을 다듬습니다.</li><li><strong>5단계 검증:</strong> 5단계 판단법으로 요구의 진위를 검증합니다.</li></ul><hr><h3 id="과후-연습" tabindex="-1">과후 연습 <a class="header-anchor" href="#과후-연습" aria-label="Permalink to “과후 연습”">​</a></h3><p>일상생활의 작은 불편 하나를 선택하고, 이번 장의 방법으로 확장해 보세요.</p><div class="tip custom-block"><p class="custom-block-title">연습 과제</p><p><strong>1. 이 불편을 설명하기</strong>(1문장)</p><ul><li>예: “사용자의 소비를 기록하는 가계부 APP을 만들고 싶다”</li></ul><p><strong>2. 가로 나누기: 서로 다른 요구를 가질 수 있는 사람군 3개 찾기</strong></p><ul><li>예: 소상공인, 유학생 부모, 프리랜서</li></ul><p><strong>3. 사람군 하나를 선택하고 세로로 깊게 파기: 그들의 완전한 장면과 진짜 감정 설명하기</strong></p><ul><li>예: 유학생 부모의 장면 - 아이가 해외에서 돈을 얼마나 쓰는지 알고 싶지만 아이가 말하지 않음</li></ul><p><strong>4. 제품 개념 재구성: “하나의 기능”에서 “하나의 해결 방안”으로 진화시키기</strong></p><ul><li>예: “유학 자금 매니저” - 단순 가계부가 아니라 부모가 아이의 해외 소비를 “마음속으로 파악”하게 해 주는 것</li></ul><p><strong>5. 검증 체크리스트로 아이디어 평가하기</strong>(부록 F 참고)</p><p><strong>분석을 커뮤니티에 공유하고 다른 학습자와 토론하세요!</strong></p></div><hr><h2 id="부록-sop-방법론" tabindex="-1">부록: SOP 방법론 <a class="header-anchor" href="#부록-sop-방법론" aria-label="Permalink to “부록: SOP 방법론”">​</a></h2><h3 id="부록-a-요구-분석의-5단계-판단법" tabindex="-1">부록 A: 요구 분석의 5단계 판단법 <a class="header-anchor" href="#부록-a-요구-분석의-5단계-판단법" aria-label="Permalink to “부록 A: 요구 분석의 5단계 판단법”">​</a></h3><p>아이디어가 하나 있을 때, 이것이 투자할 가치가 있는지 어떻게 빠르게 판단할 수 있을까요?</p><p><strong>1단계: 사용자 검증 - 목표 사용자 10명 찾기</strong></p><p><strong>묻지 말아야 할 질문:</strong> “내 제품을 사용할 건가요?”(거짓 양성률 90%)</p><p><strong>물어야 할 질문:</strong></p><ol><li>“지금은 이 문제를 어떻게 해결하고 있나요?”(진짜 행동 이해)</li><li>“최근 일주일 동안 이 문제가 몇 번이나 당신을 괴롭혔나요?”(빈도 이해)</li><li>“이를 해결하기 위해 돈/시간을 얼마나 썼나요?”(지불 의향 이해)</li><li>“해결 방안이 있지만 습관을 바꿔야 한다면, 의향이 있나요?”(변화 비용 이해)</li></ol><p><strong>판단 기준:</strong></p><ul><li>3명 이상의 사용자가 “매일 이 일 때문에 골치 아파요”라고 말하면 문제점일 수 있습니다.</li><li>사용자가 “꽤 흥미롭지만 급하지는 않아요”라고 말하면 대부분 가려운 지점입니다.</li><li>사용자가 “지금 XX로 해결하고 있는데 만족스럽지 않아요”라고 말하면 기회가 있습니다.</li></ul><p><strong>핵심 질문:</strong> 사용자는 지금 어떤 방법으로 이 문제를 해결하고 있나요?</p><table tabindex="0"><thead><tr><th>대체 방안 유형</th><th>설명</th><th>기회 판단</th></tr></thead><tbody><tr><td><strong>대체 방안 없음</strong></td><td>사용자가 조용히 참고 있음</td><td>큰 기회이지만 시장 교육 필요</td></tr><tr><td><strong>매우 둔한 방법 사용</strong></td><td>Excel, 수작업, 여러 사람 협업</td><td>좋은 기회. 사용자가 더 나은 방안을 갈망함</td></tr><tr><td><strong>여러 도구를 조합 사용</strong></td><td>A도구 + B도구 + C도구</td><td>좋은 기회. 통합에 가치가 있음</td></tr><tr><td><strong>성숙한 제품 사용</strong></td><td>하지만 사용자가 만족하지 않음</td><td>기회가 있지만 차별화 필요</td></tr><tr><td><strong>성숙한 제품 사용</strong></td><td>사용자가 매우 만족함</td><td>기회가 작음. 파괴적 혁신이 아니면 어려움</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">“파괴적 혁신”이란 무엇인가?</p><p><strong>간단한 정의:</strong> 제품을 더 좋게 만드는 것이 아니라, 더 단순하거나 저렴한 방식으로 이전에 무시되던 사용자 집단을 서비스하는 것입니다.</p><p><strong>예시:</strong></p><ul><li>전통 휴대폰 → 스마트폰(기능이 더 많은 것이 아니라 상호작용 방식이 완전히 다름)</li><li>전통 택시 → Didi(차가 더 좋은 것이 아니라 언제 어디서나 차량 호출이 가능해짐)</li><li>전통 서점 → 전자책(책이 더 많은 것이 아니라 휴대와 구매가 더 편해짐)</li></ul><p><strong>핵심:</strong> 파괴적 혁신은 보통 “저가 시장” 또는 “새 사용자 집단”에서 시작해 점차 위쪽으로 잠식합니다.</p></div><p><strong>사례:</strong></p><ul><li>당뇨병 환자가 지금 “경험 + 추측”으로 식단을 통제함(매우 둔한 방법) - 기회 큼</li><li>일반 다이어터가 Bohe Health를 사용함(성숙한 제품, 만족도 중간) - 세분화 기회 있음</li><li>학생이 WeChat 그룹으로 중고 거래를 함(여러 도구 조합) - 통합 기회 있음</li></ul><p><strong>가장 효과적인 방법: 사전 판매 또는 예약금</strong></p><p><strong>조작 단계:</strong></p><ol><li>간단한 랜딩 페이지를 만들어 제품 개념을 설명합니다.</li><li>“사전 판매” 또는 “예약” 버튼을 놓습니다.</li><li>몇 명이 비용을 지불하려 하는지 봅니다. 1위안이어도 됩니다.</li></ol><p><strong>판단 기준:</strong></p><ul><li>예약금을 내는 사용자 &gt; 10%: 요구가 진짜이며 만들 가치가 있음</li><li>예약금을 내는 사용자 5-10%: 요구는 존재하지만 다듬어야 함</li><li>예약금을 내는 사용자 &lt; 5%: 요구가 성립하지 않거나 제품 개념에 문제가 있음</li></ul><p><strong>주의:</strong> “살게요”라고 말하는 사람은 많습니다. 실제로 돈을 내는 사람만이 목표 사용자입니다.</p><p><strong>간단 공식:</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>잠재 시장 규모 = 목표 사용자 수 × 지불 의향 × 객단가</span></span></code></pre></div><p><strong>사례: 캠퍼스 중고 거래 플랫폼</strong></p><ul><li>목표 사용자: 전국 대학생 4,000만 명</li><li>중고 거래 요구가 있는 사람: 50% = 2,000만 명</li><li>플랫폼을 사용할 의향이 있는 사람: 10% = 200만 명</li><li>연간 거래 빈도: 2회</li><li>플랫폼 수수료: 5%</li><li>평균 객단가: 100위안</li><li>잠재 시장 규모 = 200만 × 2 × 100 × 5% = 연 2,000만 위안</li></ul><p><strong>판단 기준:</strong></p><ul><li>시장 규모 &gt; 10억 위안: 큰 트랙, 만들 가치 있음</li><li>시장 규모 1-10억 위안: 중소 트랙, 만들 수 있지만 상한이 뚜렷함</li><li>시장 규모 &lt; 1억 위안: 니치 시장, 부업 또는 작지만 아름다운 제품에 적합</li></ul><p><strong>핵심 질문:</strong> 제품이 성공하면 다른 사람이 베끼면 어떻게 할까요?</p><p><strong>흔한 해자 유형:</strong></p><table tabindex="0"><thead><tr><th>해자 유형</th><th>설명</th><th>예시</th></tr></thead><tbody><tr><td><strong>네트워크 효과</strong></td><td>사용자가 많을수록 제품 가치가 커짐</td><td>WeChat, Didi</td></tr><tr><td><strong>데이터 축적</strong></td><td>데이터가 많을수록 알고리즘이 정확해짐</td><td>Toutiao, Douyin</td></tr><tr><td><strong>브랜드 인식</strong></td><td>사용자 마음속 점유</td><td>Coca-Cola, Nike</td></tr><tr><td><strong>규모 효과</strong></td><td>규모가 클수록 비용이 낮아짐</td><td>JD Logistics, Amazon</td></tr><tr><td><strong>기술 특허</strong></td><td>핵심 기술 장벽</td><td>Huawei, DJI</td></tr><tr><td><strong>전환 비용</strong></td><td>사용자 이전 비용이 높음</td><td>기업 소프트웨어, 운영체제</td></tr></tbody></table><p><strong>초기 프로젝트의 현실:</strong></p><ul><li>대부분 초기 프로젝트에는 뚜렷한 해자가 없습니다.</li><li>하지만 괜찮습니다. 핵심은 <strong>빨리 달리는 것</strong>입니다.</li><li>먼저 시장을 점유하고, 그다음 장벽을 세웁니다.</li></ul><hr><h3 id="부록-b-사람군을-가로로-나누는-방법" tabindex="-1">부록 B: 사람군을 가로로 나누는 방법 <a class="header-anchor" href="#부록-b-사람군을-가로로-나누는-방법" aria-label="Permalink to “부록 B: 사람군을 가로로 나누는 방법”">​</a></h3><p>“모든 XX 사용자”를 서비스하려 하지 말고, <strong>특정 사람군 하나</strong>를 찾으세요. 그들의 요구가 더 아프고 더 구체적입니다.</p><p><strong>1단계: 가능한 모든 세분 사람군 나열하기</strong></p><p>제품 개념을 대상으로 가능한 모든 사람군을 나열합니다.</p><p><strong>2단계: 각 사람군의 비즈니스 가치 평가하기</strong></p><table tabindex="0"><thead><tr><th>평가 차원</th><th>설명</th></tr></thead><tbody><tr><td>문제점 강도</td><td>이 사람군의 요구는 문제점인가, 가려운 지점인가?</td></tr><tr><td>지불 의향</td><td>해결 방안에 얼마를 낼 의향이 있는가?</td></tr><tr><td>시장 규모</td><td>이 사람군은 몇 명인가?</td></tr><tr><td>경쟁 정도</td><td>기존 해결 방안은 만족스러운가?</td></tr><tr><td>사람군에 대한 이해</td><td>당신은 이 사람군을 이해하는가? 접촉 채널이 있는가?</td></tr></tbody></table><p><strong>3단계: 사람군 하나를 선택해 깊게 분석하기</strong></p><p>다음 조건에 맞는 사람군을 선택합니다.</p><ul><li>문제점이 가장 아픔</li><li>지불 의향이 가장 강함</li><li>당신이 가장 잘 이해함</li><li>경쟁이 상대적으로 치열하지 않음</li></ul><div class="tip custom-block"><p class="custom-block-title">나누기 예시</p><p><strong>제품 개념:</strong> 가계부 APP</p><table tabindex="0"><thead><tr><th>세분 사람군</th><th>문제점</th><th>지불 의향</th><th>시장 규모</th><th>경쟁 정도</th></tr></thead><tbody><tr><td>일반 직장인</td><td>기록이 번거로움</td><td>낮음</td><td>큼</td><td>높음</td></tr><tr><td>소상공인</td><td>개인/회사 지출이 섞임</td><td>높음</td><td>중간</td><td>중간</td></tr><tr><td>프리랜서</td><td>수입이 불안정하고 현금흐름 예측 필요</td><td>높음</td><td>중간</td><td>중간</td></tr><tr><td>유학생 부모</td><td>아이가 돈을 얼마나 쓰는지 알고 싶지만 아이가 말하지 않음</td><td>높음</td><td>작음</td><td>낮음</td></tr></tbody></table><p><strong>선택:</strong> 유학생 부모(문제점이 가장 아프고, 지불 의향이 높으며, 경쟁이 상대적으로 낮음)</p></div><hr><h3 id="부록-c-장면을-세로로-깊게-파는-방법" tabindex="-1">부록 C: 장면을 세로로 깊게 파는 방법 <a class="header-anchor" href="#부록-c-장면을-세로로-깊게-파는-방법" aria-label="Permalink to “부록 C: 장면을 세로로 깊게 파는 방법”">​</a></h3><p>사람군을 찾은 뒤 단일 기능에 머무르지 말고 사용자의 <strong>완전한 장면</strong>을 이해해야 합니다.</p><p><strong>1단계: 사용자의 하루 설명하기</strong></p><p>아침부터 밤까지, 사용자가 제품을 사용할 때의 완전한 장면을 설명합니다.</p><p><strong>2단계: 각 장면의 문제점 분석하기</strong></p><p>각 장면에서 사용자는 어떤 문제를 만났나요? 어떤 감정이 있나요?</p><p><strong>3단계: 감정 접점 찾기</strong></p><p>두려움, 불안, 무력감, 고립감, 분노, 후회...</p><p><strong>4단계: 가치 재구성하기</strong></p><p>장면과 감정을 바탕으로 제품 가치를 재구성합니다.</p><div class="tip custom-block"><p class="custom-block-title">깊게 파기 예시</p><p><strong>사람군:</strong> 산후 엄마</p><table tabindex="0"><thead><tr><th>시간</th><th>장면</th><th>문제점</th><th>감정</th></tr></thead><tbody><tr><td>아침 6시</td><td>아기가 막 잠들었고 30분 여유가 있음</td><td>어떤 동작이 안전한지 모름</td><td>두려움</td></tr><tr><td>오전 10시</td><td>아기를 안고 재우며 허리가 매우 아픔</td><td>손이 비어 있지 않고 회복 운동을 하고 싶음</td><td>불안</td></tr><tr><td>오후 3시</td><td>아기가 자고 운동하고 싶음</td><td>몸이 매우 피곤하고 아직 해도 되는지 모름</td><td>무력감</td></tr><tr><td>밤 8시</td><td>드디어 시간이 생김</td><td>거울 속 자신을 보며 인생이 끝났다고 느낌</td><td>우울</td></tr><tr><td>장기</td><td>이해해 주는 사람이 없음</td><td>나만 이렇게 고통스럽다고 느낌</td><td>고립감</td></tr></tbody></table><p><strong>가치 재구성:</strong> “피트니스 도구”에서 “회복 코치 + 심리 지원자”로 업그레이드</p></div><hr><h3 id="부록-d-평범한-idea에서-좋은-아이디어로-바뀌는-더-많은-예시" tabindex="-1">부록 D: 평범한 idea에서 좋은 아이디어로 바뀌는 더 많은 예시 <a class="header-anchor" href="#부록-d-평범한-idea에서-좋은-아이디어로-바뀌는-더-많은-예시" aria-label="Permalink to “부록 D: 평범한 idea에서 좋은 아이디어로 바뀌는 더 많은 예시”">​</a></h3><h4 id="예시-1-가계부-app-에서-유학-자금-매니저-까지" tabindex="-1">예시 1: “가계부 APP”에서 “유학 자금 매니저”까지 <a class="header-anchor" href="#예시-1-가계부-app-에서-유학-자금-매니저-까지" aria-label="Permalink to “예시 1: “가계부 APP”에서 “유학 자금 매니저”까지”">​</a></h4><p><strong>평범한 생각:</strong> 자동 가계부 APP. 은행카드를 연결해 소비를 자동 분류합니다.</p><p><strong>문제:</strong> 시장에는 이미 Suishouji, Wacai, Alipay 청구서 등이 있습니다.</p><p><strong>가로 나누기:</strong></p><ul><li>유학생 부모: 아이가 외국에서 돈을 얼마나 쓰고, 초과 지출하는지 알고 싶음</li></ul><p><strong>세로 깊게 파기:</strong></p><ul><li>문제점은 “가계부”가 아니라 <strong>“통제감을 잃은 느낌”</strong>입니다. 아이가 얼마를 쓰는지 모르고, 어디에 쓰는지도 모릅니다.</li><li>장면: 매달 신용카드 청구서를 보지만 아이는 무엇에 썼는지 절대 먼저 말하지 않습니다.</li></ul><p><strong>재구성 후:</strong> “유학 자금 매니저” - 단순 가계부가 아니라 부모가 아이의 해외 소비를 “마음속으로 파악”하게 하는 것</p><p><strong>핵심 기능:</strong></p><ul><li>자녀 소비 실시간 동기화</li><li>초과 지출 경고</li><li>월별 소비 분석 보고서</li><li>같은 유형 학생 소비 비교(“당신의 아이는 평균보다 20% 더 썼습니다”)</li></ul><hr><h4 id="예시-2-뽀모도로-도구-에서-원격근무-증명-까지" tabindex="-1">예시 2: “뽀모도로 도구”에서 “원격근무 증명”까지 <a class="header-anchor" href="#예시-2-뽀모도로-도구-에서-원격근무-증명-까지" aria-label="Permalink to “예시 2: “뽀모도로 도구”에서 “원격근무 증명”까지”">​</a></h4><p><strong>평범한 생각:</strong> 사용자가 집중해 일하도록 돕는 뽀모도로 APP.</p><p><strong>문제:</strong> 휴대폰 기본 화면 사용 시간, Forest, Tomato ToDo 등이 있습니다.</p><p><strong>가로 나누기:</strong></p><ul><li>원격근무자: 상사에게 “내가 정말 일하고 있다”는 것을 증명해야 함</li></ul><p><strong>세로 깊게 파기:</strong></p><ul><li>문제점은 “집중하지 못함”이 아니라 <strong>“신뢰 위기”</strong>입니다. 상사는 나를 볼 수 없는데 어떻게 내가 일하고 있다는 것을 증명할까요?</li><li>장면: 매일 퇴근할 때 상사가 “오늘 일은 어땠나요?”라고 묻지만 증명할 방법이 없습니다.</li></ul><p><strong>재구성 후:</strong> “원격근무 증명” - 원격근무자가 고용주와의 신뢰를 구축하도록 돕기</p><p><strong>핵심 기능:</strong></p><ul><li>자동 근무 시간 추적</li><li>생산성 보고서</li><li>화면 활동 요약(프라이버시 보호 버전)</li><li>매일 자동으로 “업무 보고서”를 생성해 상사에게 전송</li></ul><hr><h4 id="예시-3-중고책-거래-에서-그림책-도서관-까지" tabindex="-1">예시 3: “중고책 거래”에서 “그림책 도서관”까지 <a class="header-anchor" href="#예시-3-중고책-거래-에서-그림책-도서관-까지" aria-label="Permalink to “예시 3: “중고책 거래”에서 “그림책 도서관”까지”">​</a></h4><p><strong>평범한 생각:</strong> 중고책 거래 플랫폼.</p><p><strong>문제:</strong> Duozhuayu, Xianshu, Kongfz 같은 중고책 사이트가 있습니다.</p><p><strong>가로 나누기:</strong></p><ul><li>엄마 집단: 아이가 그림책을 다 보면 방치되지만 새 책은 비쌈</li></ul><p><strong>세로 깊게 파기:</strong></p><ul><li>문제점은 “책이 비쌈”이 아니라 <strong>“그림책 생명주기가 짧음”</strong>입니다. 아이가 3살에 본 책을 4살에는 보지 않습니다.</li><li>장면: 집에는 그림책이 가득 쌓였고, 아이는 더 이상 보지 않지만 버리기 아깝습니다.</li></ul><p><strong>재구성 후:</strong> “집으로 오는 그림책 도서관” - 중고책 판매가 아니라 그림책의 “사용권 대여” 제공</p><p><strong>핵심 기능:</strong></p><ul><li>그림책 구독제(매달 연령에 맞는 그림책 5권 배송, 다 읽으면 반납하고 새 책으로 교환)</li><li>읽기 진행 추적</li><li>연령별 추천</li><li>소독 보장</li></ul><hr><h3 id="부록-e-ai-대화로-제품-개념을-다듬는-5단계-방법" tabindex="-1">부록 E: AI 대화로 제품 개념을 다듬는 5단계 방법 <a class="header-anchor" href="#부록-e-ai-대화로-제품-개념을-다듬는-5단계-방법" aria-label="Permalink to “부록 E: AI 대화로 제품 개념을 다듬는 5단계 방법”">​</a></h3><p>여러 라운드의 AI 대화를 통해 평범한 idea를 점차 실행 가능한 정확한 제품 개념으로 다듬습니다.</p><p><strong>조작:</strong></p><ul><li>초기 생각을 설명합니다. 거칠어도 괜찮습니다.</li><li>AI에게 당신의 걱정을 말합니다. 경쟁이 치열하다, 차별화 방법을 모르겠다 등.</li></ul><p><strong>프롬프트:</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[제품 개념]을 만들고 싶습니다.</span></span>
<span class="line"><span>하지만 [문제/걱정]을 발견했습니다.</span></span></code></pre></div><p><strong>조작:</strong></p><ul><li>AI에게 최소 기능 제품 계획을 세우게 합니다.</li><li>기술 구현 난이도와 비용을 논의합니다.</li><li>검증 지표를 설정합니다.</li></ul><p><strong>프롬프트:</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>다음을 도와주세요:</span></span>
<span class="line"><span>1. MVP 계획하기</span></span>
<span class="line"><span>2. 구체적인 기술 구현 제안 제시하기</span></span>
<span class="line"><span>3. 비용 추산하기</span></span>
<span class="line"><span>4. 검증 지표 설정하기</span></span></code></pre></div><p><strong>조작:</strong></p><ul><li>기술 구현 난이도?</li><li>콘텐츠 제작 비용?</li><li>홍보 비용?</li><li>사용자 획득 난이도?</li></ul><p><strong>프롬프트:</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>저는 다음이 걱정됩니다:</span></span>
<span class="line"><span>1. [걱정1]</span></span>
<span class="line"><span>2. [걱정2]</span></span>
<span class="line"><span>3. [걱정3]</span></span></code></pre></div><p><strong>조작:</strong></p><ul><li>당신의 걱정에 대해 구체적인 제안을 받습니다.</li><li>여러 방안을 비교하고 최적안을 선택합니다.</li><li>비용을 추산합니다.</li></ul><p><strong>프롬프트:</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>제 걱정에 대해 구체적인 해결 방안을 제시해 주세요.</span></span></code></pre></div><p><strong>조작:</strong></p><ul><li>명확한 실행 계획을 정리합니다.</li><li>검증 지표를 설정합니다.</li><li>도달하지 못하면 즉시 방향을 조정합니다.</li></ul><p><strong>프롬프트:</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>명확한 실행 계획을 정리해 주세요.</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">핵심 기술</p><ul><li><strong>여러 라운드 대화:</strong> 한 번의 대화로 완벽한 답을 기대하지 말고 여러 번 반복합니다.</li><li><strong>정보 제공:</strong> 당신의 관찰, 경험, 주변 사람의 피드백을 AI에게 알려 줍니다.</li><li><strong>AI에 의문 제기:</strong> AI의 제안이 합리적이지 않다면 즉시 지적합니다.</li><li><strong>실행에 집중:</strong> 마지막에는 반드시 구체적인 실행 계획으로 내려옵니다.</li></ul></div><hr><h3 id="부록-f-요구-검증-체크리스트" tabindex="-1">부록 F: 요구 검증 체크리스트 <a class="header-anchor" href="#부록-f-요구-검증-체크리스트" aria-label="Permalink to “부록 F: 요구 검증 체크리스트”">​</a></h3><p>시간을 들여 개발하기로 결정하기 전에, 아래 체크리스트로 아이디어를 검증하세요. <strong>핵심 질문은: 사용자가 이것에 비용을 지불할까?</strong> 입니다.</p><div class="tip custom-block"><p class="custom-block-title">요구 검증 체크리스트</p><p><strong>1. 사용자 페르소나 명확도</strong></p><ul><li>☐ 목표 사용자를 한 문장으로 설명할 수 있는가?</li><li>☐ 그들이 현재 쓰는 대체 방안이 무엇인지 말할 수 있는가?</li><li>☐ 그들의 사용 장면의 구체적인 세부 사항을 설명할 수 있는가?</li><li>☐ 이 사람군은 지불 능력이 있는가?</li></ul><p><strong>2. 문제점 강도 평가</strong></p><ul><li>☐ 사용자가 지금 이 문제를 해결하기 위해 어떤 대가를 치르는가? 시간/돈/에너지.</li><li>☐ 이 문제를 해결하지 않으면 어떤 결과가 생기는가?</li><li>☐ 사용자가 이미 해결 방안을 찾고 있는가?</li><li>☐ 사용자가 이 문제를 해결하기 위해 얼마를 지불할 의향이 있는가?</li></ul><p><strong>3. 해결 방안 차별화</strong></p><ul><li>☐ 기존 방안과 비교해 당신의 장점은 무엇인가?</li><li>☐ 이 장점이 사용자가 전환할 만큼 충분한가?</li><li>☐ 대형 플랫폼이 당신의 기능을 베끼는 난이도는 높은가?</li><li>☐ 당신의 차별화는 사용자 결제를 지탱할 만큼 충분한가?</li></ul><p><strong>4. 비즈니스 모델 가능성</strong></p><ul><li>☐ 사용자가 이것에 비용을 지불할 의향이 있는가? 얼마를 낼까? 반드시 실제 테스트해야 합니다.</li><li>☐ 고객 획득 비용은 대략 얼마인가?</li><li>☐ 사용자 생애 가치(LTV)가 고객 획득 비용(CAC)을 덮을 수 있는가?</li><li>☐ 다른 수익화 방식이 있는가? 광고, 부가 서비스, B2B 등.</li></ul><p><strong>5. 빠른 검증 방안</strong></p><ul><li>☐ 최소 비용(1-2주)으로 테스트 가능한 프로토타입을 만들 수 있는가?</li><li>☐ 목표 사용자 10명을 찾아 인터뷰할 수 있는가?</li><li>☐ 핵심 가설을 검증할 실험을 설계할 수 있는가?</li><li>☐ 사용자에게 예약금을 선불로 받아 지불 의향을 검증할 수 있는가?</li></ul></div><p><strong>“이 제품을 사용할 건가요?”</strong> 같은 질문은 하지 마세요. 이런 질문은 모두 거짓 양성 답변을 얻습니다.</p><p><strong>이렇게 물어야 합니다:</strong></p><ul><li>“지금은 이 문제를 어떻게 해결하고 있나요?”(진짜 행동 이해)</li><li>“최근 일주일 동안 이 문제가 몇 번이나 당신을 괴롭혔나요?”(빈도 이해)</li><li>“해결 방안이 있지만 지금 습관을 바꿔야 한다면, 의향이 있나요?”(변화 비용 이해)</li><li>“XX위안을 받는다면 구매할 건가요?”(지불 의향 이해)</li></ul><p><strong>가장 좋은 검증:</strong> 사용자에게 예약금을 선불로 받는 것입니다. 비용을 지불하겠다고 말하는 사람은 많지만, 실제로 돈을 내는 사람만이 목표 사용자입니다.</p><p><strong>핵심 지표:</strong></p><ul><li>예약금을 낼 의향이 있는 사용자 비율 &gt; 10%: 요구가 진짜이며 투자할 가치가 있음</li><li>예약금을 낼 의향이 있는 사용자 비율 5-10%: 요구는 존재하지만 다듬어야 함</li><li>예약금을 낼 의향이 있는 사용자 비율 &lt; 5%: 요구가 성립하지 않거나 제품 개념에 문제가 있음</li></ul><hr><h2 id="이-장의-소결" tabindex="-1">이 장의 소결 <a class="header-anchor" href="#이-장의-소결" aria-label="Permalink to “이 장의 소결”">​</a></h2><p>이번 장에서는 샤오밍의 이야기를 통해 제품 관리자의 관점으로 제품 아이디어를 바라보는 법을 배웠습니다. <strong>핵심은 항상 사용자가 이것에 비용을 지불할까?</strong> 입니다.</p><div class="info custom-block"><p class="custom-block-title">핵심 요점</p><p><strong>1. 진짜 요구의 세 가지 기준:</strong></p><ul><li>사용자가 비용을 지불할 의향이 있음. 가장 중요한 기준입니다.</li><li>사용자가 행동을 바꿀 의향이 있음.</li><li>해결 방안이 없을 때 사용자가 큰 손실을 봄.</li></ul><p><strong>2. 평범한 idea에서 누군가 비용을 지불할 제품으로 가는 길:</strong></p><ul><li><strong>가로 나누기:</strong> 특정 사람군을 찾습니다. 더 세분화할수록 지불 의향이 강합니다.</li><li><strong>세로 깊게 파기:</strong> 완전한 장면을 이해하고, 기능뿐 아니라 감정을 해결합니다.</li><li><strong>가치 재구성:</strong> 도구에서 해결 방안으로 진화시켜 결제 이유를 만듭니다.</li></ul><p><strong>3. 가짜 요구의 함정 피하기:</strong></p><ul><li>가짜 문제점 해결하기(문제점이 아니라 가려운 지점)</li><li>시장 규모가 너무 작아 비즈니스 모델을 지탱할 수 없음</li><li>해결 방안이 문제보다 더 복잡함</li></ul><p><strong>4. 지불 의향 검증 방법:</strong></p><ul><li>목표 사용자 10명을 찾아 심층 인터뷰</li><li>사용자에게 예약금을 선불로 받게 해 진짜 의향 검증</li><li>예약금을 낼 의향이 있는 사용자 비율이 10%를 넘어야 투자할 가치가 있음</li></ul><p><strong>5. AI 대화로 제품 개념 다듬기:</strong></p><ul><li>여러 라운드로 반복하며 계속 최적화</li><li>실행에 집중하고 실행 계획으로 내리기</li><li>검증 지표를 설정하고 즉시 조정</li></ul></div><p><strong>기억하세요:</strong> 좋은 제품 관리자는 허공에서 요구를 창조하는 사람이 아니라, <strong>무시되고, 과소평가되고, 잘못 충족되고 있는</strong> 진짜 요구를 발견하고, 사용자가 기꺼이 비용을 지불할 방식을 찾는 사람입니다.</p><p>다음 장에서는 검증된 아이디어를 가지고, AI IDE로 그것을 상호작용 가능한 제품 프로토타입으로 바꾸는 법을 배우기 시작합니다.</p>`,337))])}}});export{m as __pageData,A as default};
